WITH store_sales AS ( SELECT s.s_store_sk, s.s_store_name, s.s_state, s.s_market_id, SUM(cs.cs_net_profit) AS total_net_profit, SUM(cs.cs_net_paid) AS total_net_paid, AVG(cs.cs_ext_discount_amt) AS avg_discount, COUNT(*) AS sales_cnt, SUM(cs.cs_ext_sales_price) AS total_sales_price FROM store s JOIN catalog_sales cs ON s.s_store_sk = cs.cs_warehouse_sk WHERE cs.cs_promo_sk IN (1096, 1170, 284) AND s.s_state = 'CA' AND cs.cs_sold_date_sk BETWEEN 2450000 AND 2451000 GROUP BY s.s_store_sk, s.s_store_name, s.s_state, s.s_market_id ) SELECT s_store_name, s_state, total_net_profit, total_net_paid, total_sales_price, avg_discount, sales_cnt, total_net_profit / NULLIF(total_net_paid, 0) AS profit_to_paid_ratio, RANK() OVER (ORDER BY total_net_profit DESC) AS profit_rank FROM store_sales ORDER BY profit_rank LIMIT 10
